description:
Implement `MyPartial<T>` — a mapped type that makes all properties of `T` optional — without using the built-in `Partial<T>`.

Also implement `partialize<T>(obj: T): MyPartial<T>` that returns the same object typed as `MyPartial<T>`.

**Example:**
```ts
type User = { name: string; age: number };
type PartialUser = MyPartial<User>;
// { name?: string; age?: number }
```

starter_code:
export type MyPartial<T> = // your type here

export function partialize<T>(obj: T): MyPartial<T> {
  return obj as MyPartial<T>;
}

test_suite:
test('partialize returns the same object', () => {
  const obj = { name: 'Alice', age: 30 };
  expect(partialize(obj)).toEqual(obj);
});

test('type-level: all properties become optional', () => {
  type T = MyPartial<{ a: number; b: string }>;
  type Check = T extends { a?: number; b?: string } ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

test('type-level: MyPartial matches built-in Partial', () => {
  type T = { x: boolean; y: number };
  type Check = MyPartial<T> extends Partial<T> ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

// __hidden__
test('accepts partial object at runtime', () => {
  const partial: MyPartial<{ name: string; age: number }> = { name: 'Bob' };
  expect(partial.name).toBe('Bob');
  expect(partial.age).toBeUndefined();
});

solution:
export type MyPartial<T> = { [K in keyof T]?: T[K] };

export function partialize<T>(obj: T): MyPartial<T> {
  return obj as MyPartial<T>;
}
